values
('bmlt-clinpharm1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Pharmacology is the study of:","translation":"","options":["Drugs and their effects on living systems","Only surgical procedures","Only infectious organisms","Hospital accounting"],"correctIndex":0,"explanation":"Pharmacology studies drugs, including their actions, uses and adverse effects.","explanationNe":"Pharmacology ले औषधि र जीवित शरीरमा पर्ने प्रभावको अध्ययन गर्छ।","topic":"Introduction"}'::jsonb,true),
('bmlt-clinpharm1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Pharmacokinetics describes:","translation":"","options":["What the body does to a drug","What a drug does to the body","Only drug toxicity","Only drug pricing"],"correctIndex":0,"explanation":"Pharmacokinetics includes absorption, distribution, metabolism and excretion (ADME).","explanationNe":"औषधि शरीरमा कसरी अवशोषित, वितरण, मेटाबोलाइज र निष्कासित हुन्छ भन्ने अध्ययन हो।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Pharmacodynamics describes:","translation":"","options":["What a drug does to the body","How the body eliminates a drug only","How drugs are packaged","How prescriptions are stored"],"correctIndex":0,"explanation":"Pharmacodynamics concerns drug effects and mechanisms of action.","explanationNe":"औषधिले शरीरमा पार्ने प्रभाव र काम गर्ने तरिका pharmacodynamics हो।","topic":"Pharmacodynamics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"The route that generally provides the fastest systemic effect is:","translation":"","options":["Intravenous","Oral","Topical","Rectal"],"correctIndex":0,"explanation":"Intravenous administration delivers a drug directly into the circulation.","explanationNe":"IV बाट औषधि सिधै रक्तसञ्चारमा पुग्ने भएकाले प्रभाव छिटो देखिन सक्छ।","topic":"Routes of administration"}'::jsonb,true),
('bmlt-clinpharm1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"A drug given by mouth is administered by which route?","translation":"","options":["Oral","Intramuscular","Intravenous","Intradermal"],"correctIndex":0,"explanation":"Oral administration means swallowing a medicine for absorption through the gastrointestinal tract.","explanationNe":"मुखबाट औषधि सेवन गर्नु oral route हो।","topic":"Routes of administration"}'::jsonb,true),
('bmlt-clinpharm1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Bioavailability refers to the fraction of an administered dose that:","translation":"","options":["Reaches systemic circulation unchanged","Binds permanently to plasma proteins","Is removed in faeces only","Is stored in the stomach"],"correctIndex":0,"explanation":"Bioavailability is the proportion of a dose reaching systemic circulation in unchanged form.","explanationNe":"दिइएको मात्रामध्ये अपरिवर्तित रूपमा systemic circulation मा पुग्ने अंश bioavailability हो।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"First-pass metabolism most commonly affects drugs given by the:","translation":"","options":["Oral route","Intravenous route","Inhalational route","Topical route"],"correctIndex":0,"explanation":"Orally absorbed drugs may be metabolized in the intestinal wall and liver before reaching systemic circulation.","explanationNe":"मुखबाट लिइएका केही औषधि रक्तसञ्चारमा पुग्नुअघि आन्द्रा र कलेजोमा मेटाबोलाइज हुन्छन्।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"The major organ responsible for metabolism of many drugs is the:","translation":"","options":["Liver","Skin","Spleen","Pancreas"],"correctIndex":0,"explanation":"The liver contains enzymes that metabolize many medicines.","explanationNe":"धेरै औषधिको मेटाबोलिज्म मुख्यतः कलेजोमा हुन्छ।","topic":"Drug metabolism"}'::jsonb,true),
('bmlt-clinpharm1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"The major organ responsible for excretion of many drugs and metabolites is the:","translation":"","options":["Kidney","Thyroid","Lung","Stomach"],"correctIndex":0,"explanation":"The kidneys eliminate many drugs and metabolites through urine.","explanationNe":"धेरै औषधि र तिनका मेटाबोलाइट मिर्गौलाबाट पिसाबमा निष्कासित हुन्छन्।","topic":"Drug excretion"}'::jsonb,true),
('bmlt-clinpharm1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"A drug''s half-life is the time required for its plasma concentration to:","translation":"","options":["Decrease by 50%","Become zero immediately","Double","Reach its maximum"],"correctIndex":0,"explanation":"Half-life is the time for plasma drug concentration to fall by half.","explanationNe":"औषधिको plasma concentration आधा हुन लाग्ने समय half-life हो।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"An adverse drug reaction is:","translation":"","options":["A harmful and unintended response at normal doses","A desired therapeutic effect","A medicine''s brand name","A harmless change in packaging"],"correctIndex":0,"explanation":"An adverse drug reaction is a harmful, unintended response occurring at doses normally used.","explanationNe":"सामान्य मात्रामा औषधि प्रयोग गर्दा हुने हानिकारक र अनिच्छित प्रतिक्रिया adverse drug reaction हो।","topic":"Adverse drug reactions"}'::jsonb,true),
('bmlt-clinpharm1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"A contraindication is a condition in which a drug:","translation":"","options":["Should not be used because it may cause harm","Must always be doubled","Has no expiry date","Must be given intravenously"],"correctIndex":0,"explanation":"A contraindication is a patient condition or factor that makes a treatment inadvisable.","explanationNe":"औषधि प्रयोग गर्दा हानि हुन सक्ने अवस्था contraindication हो।","topic":"Safe prescribing"}'::jsonb,true),
('bmlt-clinpharm1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"An agonist is a drug that:","translation":"","options":["Activates a receptor to produce a response","Blocks a receptor without activation","Destroys all receptors","Prevents drug absorption"],"correctIndex":0,"explanation":"An agonist binds to and activates a receptor.","explanationNe":"Agonist ले receptor मा बाँधिएर त्यसलाई सक्रिय बनाउँछ।","topic":"Drug receptors"}'::jsonb,true),
('bmlt-clinpharm1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"An antagonist generally:","translation":"","options":["Blocks or reduces receptor activation","Always activates the receptor fully","Increases absorption in all cases","Acts only as a vitamin"],"correctIndex":0,"explanation":"An antagonist binds to a receptor and prevents or reduces agonist action.","explanationNe":"Antagonist ले receptor को सक्रियता रोक्छ वा घटाउँछ।","topic":"Drug receptors"}'::jsonb,true),
('bmlt-clinpharm1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Which is a common example of an analgesic?","translation":"","options":["Paracetamol","Amoxicillin","Omeprazole","Cetirizine"],"correctIndex":0,"explanation":"Paracetamol is commonly used to relieve pain and reduce fever.","explanationNe":"Paracetamol दुखाइ र ज्वरो कम गर्न प्रयोग हुने औषधि हो।","topic":"Analgesics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Amoxicillin belongs to which drug class?","translation":"","options":["Penicillin antibiotic","Antifungal","Antiviral","Antacid"],"correctIndex":0,"explanation":"Amoxicillin is a beta-lactam antibiotic in the penicillin group.","explanationNe":"Amoxicillin penicillin समूहको beta-lactam antibiotic हो।","topic":"Antibiotics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Antibiotics are primarily used to treat infections caused by:","translation":"","options":["Bacteria","Viruses only","Allergy","Vitamin deficiency"],"correctIndex":0,"explanation":"Antibiotics act against susceptible bacteria and do not treat viral infections.","explanationNe":"Antibiotics संवेदनशील ब्याक्टेरियाविरुद्ध प्रयोग हुन्छन्; भाइरसमा काम गर्दैनन्।","topic":"Antibiotics"}'::jsonb,true),
('bmlt-clinpharm1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Which drug class reduces gastric acid secretion by blocking the proton pump?","translation":"","options":["Proton pump inhibitors","Antihistamines H1","Loop diuretics","Beta blockers"],"correctIndex":0,"explanation":"Proton pump inhibitors inhibit the gastric H+/K+ ATPase in parietal cells.","explanationNe":"Proton pump inhibitor ले पेटका parietal cell को proton pump रोक्छ।","topic":"Gastrointestinal drugs"}'::jsonb,true),
('bmlt-clinpharm1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Insulin is primarily used in the management of:","translation":"","options":["Diabetes mellitus","Asthma","Peptic ulcer","Tuberculosis"],"correctIndex":0,"explanation":"Insulin lowers blood glucose and is essential in type 1 diabetes and used in selected type 2 cases.","explanationNe":"Insulin ले रगतको glucose घटाउँछ र विशेषगरी type 1 diabetes मा आवश्यक हुन्छ।","topic":"Endocrine drugs"}'::jsonb,true),
('bmlt-clinpharm1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Salbutamol is commonly used as a:","translation":"","options":["Short-acting bronchodilator","Anticoagulant","Antifungal","Antacid"],"correctIndex":0,"explanation":"Salbutamol is a short-acting beta-2 agonist that relaxes bronchial smooth muscle.","explanationNe":"Salbutamol short-acting beta-2 agonist हो, जसले श्वासनलीको मांसपेशी खुकुलो बनाउँछ।","topic":"Respiratory drugs"}'::jsonb,true),
('bmlt-clinpharm1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"An antihistamine such as cetirizine is commonly used to relieve:","translation":"","options":["Allergic symptoms","Bacterial sepsis","Hypertension emergency","Hypoglycaemia"],"correctIndex":0,"explanation":"Cetirizine blocks peripheral H1 receptors and reduces allergic symptoms.","explanationNe":"Cetirizine ले H1 receptor रोक्दै एलर्जीका लक्षण घटाउँछ।","topic":"Antihistamines"}'::jsonb,true),
('bmlt-clinpharm1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"A drug interaction occurs when:","translation":"","options":["One drug or substance alters the effect of another","A drug reaches its expiry date","A tablet changes its colour in sunlight only","A prescription is signed"],"correctIndex":0,"explanation":"Interactions can increase, decrease or otherwise modify a medicine''s effects or risks.","explanationNe":"एउटा औषधि वा पदार्थले अर्को औषधिको प्रभाव परिवर्तन गर्नु drug interaction हो।","topic":"Drug interactions"}'::jsonb,true),
('bmlt-clinpharm1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"The safest action when a patient reports a history of severe penicillin allergy is to:","translation":"","options":["Document it and alert the prescribing clinician before related therapy","Ignore it if the medicine is oral","Give a double dose","Remove the allergy record"],"correctIndex":0,"explanation":"A serious allergy history must be documented and considered before prescribing related drugs.","explanationNe":"गम्भीर penicillin allergy इतिहास अभिलेख गरी औषधि दिनुअघि चिकित्सकलाई जानकारी दिनुपर्छ।","topic":"Drug allergy"}'::jsonb,true),
('bmlt-clinpharm1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"A prescription should be checked for the correct patient, medicine, dose, route and:","translation":"","options":["Frequency","Patient''s favourite colour","Clinic wall colour","Brand advertisement"],"correctIndex":0,"explanation":"Safe medication practice includes checking patient, drug, dose, route, time/frequency and documentation.","explanationNe":"सुरक्षित औषधि प्रयोगमा बिरामी, औषधि, मात्रा, मार्ग र समय/आवृत्ति जाँच्नुपर्छ।","topic":"Medication safety"}'::jsonb,true),
('bmlt-clinpharm1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"The main purpose of pharmacovigilance is to:","translation":"","options":["Detect, assess, understand and prevent adverse effects of medicines","Increase medicine sales","Replace clinical diagnosis","Eliminate all generic medicines"],"correctIndex":0,"explanation":"Pharmacovigilance monitors medicine safety and helps prevent medicine-related harm.","explanationNe":"Pharmacovigilance ले औषधिको सुरक्षा निगरानी गरी हानि रोक्न मद्दत गर्छ।","topic":"Pharmacovigilance"}'::jsonb,true),
('bmlt-clinpharm1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A medicine is absorbed from the intestine, passes through the liver and is partly metabolized before reaching systemic circulation. This is:","translation":"","options":["First-pass metabolism","Renal clearance","Receptor antagonism","Zero-order infusion"],"correctIndex":0,"explanation":"First-pass metabolism reduces the amount of some orally administered drugs reaching systemic circulation.","explanationNe":"मुखबाट लिइएको औषधि systemic circulation मा पुग्नुअघि कलेजोमा मेटाबोलाइज हुनु first-pass metabolism हो।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A drug concentration falls from 80 mg/L to 40 mg/L in four hours. Its half-life is:","translation":"","options":["4 hours","2 hours","8 hours","40 hours"],"correctIndex":0,"explanation":"The concentration has decreased by half over four hours.","explanationNe":"Concentration आधा हुन चार घण्टा लागेकोले half-life ४ घण्टा हो।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A patient receives a medicine directly into a vein. Which statement is correct?","translation":"","options":["It has 100% bioavailability","It undergoes obligatory first-pass metabolism","It must be absorbed from the stomach","It always has delayed onset"],"correctIndex":0,"explanation":"An intravenous dose enters systemic circulation directly, giving complete bioavailability.","explanationNe":"IV औषधि सिधै रक्तसञ्चारमा जाने भएकाले यसको bioavailability १००% हुन्छ।","topic":"Routes of administration"}'::jsonb,true),
('bmlt-clinpharm1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A drug binds to a receptor and activates it. The drug is a/an:","translation":"","options":["Agonist","Antagonist","Enzyme inhibitor only","Chelator"],"correctIndex":0,"explanation":"Agonists activate receptors to produce a biological response.","explanationNe":"Agonist ले receptor सक्रिय गरी प्रतिक्रिया उत्पन्न गर्छ।","topic":"Drug receptors"}'::jsonb,true),
('bmlt-clinpharm1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A medicine binds to a receptor but prevents its activation by an agonist. It is a/an:","translation":"","options":["Antagonist","Full agonist","Nutrient","Prodrug activator"],"correctIndex":0,"explanation":"Receptor antagonists prevent or reduce agonist-mediated activation.","explanationNe":"Antagonist ले agonist बाट हुने receptor activation रोक्छ वा घटाउँछ।","topic":"Drug receptors"}'::jsonb,true),
('bmlt-clinpharm1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A patient taking a medicine develops an unexpected harmful reaction at a usual dose. This is best described as:","translation":"","options":["Adverse drug reaction","Therapeutic effect","Placebo response","Drug indication"],"correctIndex":0,"explanation":"An adverse drug reaction is harmful and unintended at normally used doses.","explanationNe":"सामान्य मात्रामा औषधि सेवन गर्दा भएको अनिच्छित हानिकारक प्रतिक्रिया ADR हो।","topic":"Adverse drug reactions"}'::jsonb,true),
('bmlt-clinpharm1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A patient has a documented history of anaphylaxis after penicillin. The history is most important as a:","translation":"","options":["Serious drug allergy/contraindication","Drug indication","Normal side effect","Reason to increase the dose"],"correctIndex":0,"explanation":"A prior severe immediate allergy must be considered before exposure to related medicines.","explanationNe":"पहिले anaphylaxis भएको इतिहासलाई गम्भीर allergy मानेर सम्बन्धित औषधि दिनु हुँदैन।","topic":"Drug allergy"}'::jsonb,true),
('bmlt-clinpharm1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A patient with impaired renal function is prescribed a drug mainly eliminated unchanged in urine. What may be required?","translation":"","options":["Clinical review and possible dose adjustment","Automatic dose doubling","Ignoring renal function","Changing every drug to topical form"],"correctIndex":0,"explanation":"Reduced renal clearance can cause drug accumulation, so dosing may need clinician review.","explanationNe":"मिर्गौलाको कार्यक्षमता घट्दा औषधि जम्मा हुन सक्छ, त्यसैले मात्रा चिकित्सकले पुनरावलोकन गर्नुपर्छ।","topic":"Drug excretion"}'::jsonb,true),
('bmlt-clinpharm1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A liver disease patient is prescribed a medicine extensively metabolized by the liver. Which concern is relevant?","translation":"","options":["Altered metabolism and possible drug accumulation","Guaranteed faster renal excretion","No possibility of interaction","Immediate loss of bioavailability for all drugs"],"correctIndex":0,"explanation":"Liver impairment may change metabolism and exposure to some medicines.","explanationNe":"कलेजोको रोगले केही औषधिको मेटाबोलिज्म र शरीरमा रहने मात्रा परिवर्तन गर्न सक्छ।","topic":"Drug metabolism"}'::jsonb,true),
('bmlt-clinpharm1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A patient is prescribed amoxicillin for a susceptible bacterial infection. Amoxicillin is a:","translation":"","options":["Penicillin-class beta-lactam antibiotic","Macrolide antifungal","Antiviral nucleoside analogue","H1 blocker"],"correctIndex":0,"explanation":"Amoxicillin is an aminopenicillin beta-lactam antibiotic.","explanationNe":"Amoxicillin aminopenicillin अर्थात् penicillin समूहको beta-lactam antibiotic हो।","topic":"Antibiotics"}'::jsonb,true),
('bmlt-clinpharm1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A patient asks whether antibiotics will cure influenza. The best response is:","translation":"","options":["Antibiotics do not treat influenza virus itself","Antibiotics cure all viral infections","Take antibiotics to prevent every complication","Use leftover antibiotics without review"],"correctIndex":0,"explanation":"Influenza is viral; antibiotics are not effective against the virus itself.","explanationNe":"Influenza भाइरसबाट हुने रोग हो; antibiotic ले भाइरसलाई उपचार गर्दैन।","topic":"Antibiotics"}'::jsonb,true),
('bmlt-clinpharm1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A dental patient takes paracetamol for pain. Its main therapeutic action is:","translation":"","options":["Analgesic and antipyretic","Anticoagulant","Antifungal","Bronchodilator"],"correctIndex":0,"explanation":"Paracetamol is used for pain relief and fever reduction.","explanationNe":"Paracetamol दुखाइ र ज्वरो कम गर्ने औषधि हो।","topic":"Analgesics"}'::jsonb,true),
('bmlt-clinpharm1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A patient with wheezing is prescribed salbutamol inhaler for rapid relief. Its action is:","translation":"","options":["Beta-2 receptor stimulation causing bronchodilation","H1 receptor blockade","Proton pump inhibition","Platelet aggregation"],"correctIndex":0,"explanation":"Beta-2 stimulation relaxes bronchial smooth muscle and widens airways.","explanationNe":"Beta-2 receptor सक्रिय हुँदा श्वासनलीका मांसपेशी खुकुलो भई श्वासनली खुल्छ।","topic":"Respiratory drugs"}'::jsonb,true),
('bmlt-clinpharm1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"A patient with seasonal allergic rhinitis is prescribed cetirizine. It is a/an:","translation":"","options":["H1 antihistamine","Antibiotic","Insulin preparation","Loop diuretic"],"correctIndex":0,"explanation":"Cetirizine is a second-generation H1 antihistamine.","explanationNe":"Cetirizine दोस्रो पुस्ताको H1 antihistamine हो।","topic":"Antihistamines"}'::jsonb,true),
('bmlt-clinpharm1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A patient with diabetes is prescribed insulin. Which parameter is important to monitor?","translation":"","options":["Blood glucose","Visual acuity only","Serum amylase only","Hearing threshold"],"correctIndex":0,"explanation":"Insulin can lower blood glucose and may cause hypoglycaemia, so glucose monitoring is important.","explanationNe":"Insulin ले glucose घटाउन सक्छ र hypoglycaemia हुन सक्छ, त्यसैले glucose निगरानी गर्नुपर्छ।","topic":"Endocrine drugs"}'::jsonb,true),
('bmlt-clinpharm1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A patient takes two medicines and one increases the blood concentration of the other. This is an example of:","translation":"","options":["Drug interaction","Drug tolerance only","Drug allergy necessarily","Placebo effect"],"correctIndex":0,"explanation":"One medicine can alter another''s metabolism or clearance and increase its concentration.","explanationNe":"एउटा औषधिले अर्कोको मेटाबोलिज्म वा निष्कासन घटाएर concentration बढाउन सक्छ।","topic":"Drug interactions"}'::jsonb,true),
('bmlt-clinpharm1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A medicine order has no dose written. What should the healthcare worker do?","translation":"","options":["Clarify with the prescriber before administration","Guess a standard dose","Give the maximum available dose","Ask another patient"],"correctIndex":0,"explanation":"An incomplete medication order must be clarified rather than guessed.","explanationNe":"मात्रा नलेखिएको औषधि आदेश अनुमान नगरी prescriber सँग स्पष्ट गर्नुपर्छ।","topic":"Medication safety"}'::jsonb,true),
('bmlt-clinpharm1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A patient accidentally receives a wrong medicine dose. What is the appropriate immediate approach?","translation":"","options":["Assess the patient, inform the responsible clinician and follow reporting protocol","Hide the incident","Alter the record","Wait for symptoms before telling anyone"],"correctIndex":0,"explanation":"Patient safety requires prompt assessment, escalation, documentation and incident reporting.","explanationNe":"बिरामीको अवस्था तुरुन्त जाँचेर जिम्मेवार चिकित्सकलाई जानकारी, अभिलेख र रिपोर्ट गर्नुपर्छ।","topic":"Medication error"}'::jsonb,true),
('bmlt-clinpharm1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A drug is administered repeatedly until its plasma level remains relatively stable. This is called:","translation":"","options":["Steady state","First-pass effect","Anaphylaxis","Drug antagonism"],"correctIndex":0,"explanation":"Steady state occurs when the rate of drug administration equals the rate of elimination over time.","explanationNe":"औषधि दिने दर र निष्कासन दर बराबर हुँदा steady state प्राप्त हुन्छ।","topic":"Pharmacokinetics"}'::jsonb,true),
('bmlt-clinpharm1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A loading dose is mainly used to:","translation":"","options":["Achieve a therapeutic drug concentration more rapidly","Prevent all adverse reactions","Eliminate the need for maintenance doses","Reduce drug absorption to zero"],"correctIndex":0,"explanation":"A loading dose can rapidly reach a target concentration when clinically appropriate.","explanationNe":"उपयुक्त अवस्थामा loading dose ले औषधिको लक्ष्य concentration छिटो प्राप्त गराउँछ।","topic":"Dosage principles"}'::jsonb,true),
('bmlt-clinpharm1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A medicine has a narrow therapeutic index. This means:","translation":"","options":["Small changes in dose or concentration may cause toxicity or loss of effect","It is always harmless","It has no therapeutic effect","It cannot interact with other drugs"],"correctIndex":0,"explanation":"Narrow therapeutic index drugs require careful dosing and monitoring.","explanationNe":"Narrow therapeutic index भएका औषधिमा मात्रा र concentration सावधानीपूर्वक निगरानी गर्नुपर्छ।","topic":"Drug safety"}'::jsonb,true),
('bmlt-clinpharm1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A patient is taking a medicine and develops a rash with facial swelling and breathing difficulty. What is the priority?","translation":"","options":["Treat as a possible severe allergic emergency and seek urgent medical help","Advise the patient to take the next dose","Record it only at the next visit","Recommend a higher dose"],"correctIndex":0,"explanation":"Facial swelling and breathing difficulty may indicate anaphylaxis requiring emergency response.","explanationNe":"अनुहार सुन्निनु र सास फेर्न गाह्रो हुनु anaphylaxis को संकेत हुन सक्छ; तुरुन्त आपत्कालीन उपचार चाहिन्छ।","topic":"Drug allergy"}'::jsonb,true),
('bmlt-clinpharm1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"A medication label shows an expiry date that has passed. The medicine should be:","translation":"","options":["Not used; follow safe disposal and replacement procedure","Used if the colour looks normal","Mixed with a new batch","Given at half dose"],"correctIndex":0,"explanation":"Expired medicines should not be administered; follow local disposal and replacement policy.","explanationNe":"म्याद सकिएको औषधि प्रयोग गर्नु हुँदैन; सुरक्षित विसर्जन र प्रतिस्थापन प्रक्रिया अपनाउनुपर्छ।","topic":"Medication safety"}'::jsonb,true),
('bmlt-clinpharm1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A health professional reports a suspected serious adverse drug reaction to the appropriate monitoring system. This activity is:","translation":"","options":["Pharmacovigilance","Pharmacokinetic sampling","Drug marketing","Dispensing audit only"],"correctIndex":0,"explanation":"Reporting suspected adverse reactions contributes to medicine safety monitoring.","explanationNe":"शंकास्पद औषधि प्रतिक्रिया रिपोर्ट गर्नु pharmacovigilance को भाग हो।","topic":"Pharmacovigilance"}'::jsonb,true),
